function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let i = 0;
  const n = text.length;
  while (i < n) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      field += c; i++; continue;
    }
    if (c === '"') { inQuotes = true; i++; continue; }
    if (c === ',') { row.push(field); field = ''; i++; continue; }
    if (c === '\r') { i++; continue; }
    if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; i++; continue; }
    field += c; i++;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }
  return rows.filter((r) => !(r.length === 1 && r[0] === ''));
}

const content = $('Workflow Configuration').first().json.csvContent || '';
const rows = parseCsv(content.replace(/^\uFEFF/, ''));
if (rows.length === 0) return [];
const header = rows[0];
const dataRows = rows.slice(1).map((r) => Object.fromEntries(header.map((h, idx) => [h.trim(), (r[idx] ?? '').trim()])));
return dataRows.map((r) => ({ json: { discovery_source: 'csv', raw: r } }));

const MAX_ATTEMPTS = 4;
let attempt = 1;
try { attempt = $('Compute Apify Backoff').item.json.attempt; } catch (e) { attempt = 1; }

const datasetId = $('Workflow Configuration').first().json.apifyDatasetId;
if (!datasetId) {
  return [{ json: { shouldRetry: false, succeeded: false, attempt, items: [], error: 'apify_dataset_id_not_configured' } }];
}

const resp = $input.first().json;
const networkError = !!resp.error;
const statusCode = resp.statusCode || null;
const retryableStatus = statusCode === 429 || [500, 502, 503, 504].includes(statusCode);

if (!networkError && statusCode >= 200 && statusCode < 300) {
  const items = Array.isArray(resp.body) ? resp.body : [];
  return [{ json: { shouldRetry: false, succeeded: true, attempt, items, error: null } }];
}

const canRetry = (networkError || retryableStatus) && attempt < MAX_ATTEMPTS;
const errorMessage = networkError ? String(resp.error).slice(0, 300) : `apify_fetch_failed_status_${statusCode}`;
return [{ json: { shouldRetry: canRetry, succeeded: false, attempt, items: [], error: errorMessage } }];

const BASE_DELAY_MS = 1000;
const MAX_DELAY_MS = 15000;
const prev = $input.first().json;
const nextAttempt = prev.attempt + 1;
const exp = Math.min(MAX_DELAY_MS, BASE_DELAY_MS * Math.pow(2, prev.attempt - 1));
const jitterMs = Math.floor(Math.random() * exp * 0.25);
return [{ json: { attempt: nextAttempt, delayMs: exp + jitterMs } }];

const evalResult = $('Evaluate Apify Fetch').first().json;
const cfg = $('Workflow Configuration').first().json;
if (!evalResult.succeeded) return [];
const items = (evalResult.items || []).slice(0, cfg.apifyMaxItems);
return items.map((r) => ({ json: { discovery_source: 'apify', raw: r } }));

const cfg = $('Workflow Configuration').first().json;
const items = $input.all().map((i) => i.json).slice(0, cfg.maxCandidatesPerRun);

function firstNonEmpty(...values) {
  for (const v of values) { if (typeof v === 'string' && v.trim() !== '') return v.trim(); }
  return null;
}

return items.map(({ discovery_source, raw }) => ({
  json: {
    discovery_source,
    company_name: firstNonEmpty(raw.company_name, raw.name),
    country_code: firstNonEmpty(raw.country_code, raw.country),
    official_website_url: firstNonEmpty(raw.official_website_url, raw.website, raw.website_url),
    official_careers_url: firstNonEmpty(raw.official_careers_url, raw.careers_url, raw.careers_page),
    company_id_hint: firstNonEmpty(raw.company_id_hint, raw.company_id),
    ats_provider_hint: firstNonEmpty(raw.ats_provider_hint, raw.ats_provider),
    raw_payload: raw,
  },
}));

const c = $input.first().json;
const nameValid = typeof c.company_name === 'string' && c.company_name.trim() !== '';
return [{ json: {
  ...c,
  validationStatus: nameValid ? 'valid' : 'validation_failed',
  validationReason: nameValid ? null : 'company_name is required and was missing or blank',
} }];

const c = $input.first().json;
return [{ json: {
  discovery_source: c.discovery_source,
  company_name: c.company_name,
  country_code: c.country_code,
  outcome: 'validation_failed',
  reason: c.validationReason,
  company_id: null,
  source_id: null,
  staging_id: null,
} }];

const c = $('Validate Candidate').first().json;
const resp = $input.first().json;
const networkError = !!resp.error;
const statusCode = resp.statusCode || null;
const ok = !networkError && statusCode >= 200 && statusCode < 300;

if (!ok) {
  const body = resp.body;
  const message = networkError
    ? String(resp.error).slice(0, 300)
    : (body && typeof body === 'object' && body.message ? String(body.message).slice(0, 300) : `rpc_call_failed_status_${statusCode}`);
  return [{ json: {
    discovery_source: c.discovery_source, company_name: c.company_name, country_code: c.country_code,
    outcome: 'infrastructure_failed', reason: message,
    company_id: null, source_id: null, staging_id: null,
  } }];
}

const row = Array.isArray(resp.body) ? resp.body[0] : resp.body;
return [{ json: {
  discovery_source: c.discovery_source, company_name: c.company_name, country_code: c.country_code,
  outcome: row.outcome, reason: null,
  company_id: row.out_company_id || null, source_id: row.out_source_id || null, staging_id: row.out_staging_id || null,
} }];

const cfg = $('Workflow Configuration').first().json;
const results = $input.all().map((i) => i.json);
const startedAtMs = new Date(cfg.startedAt).getTime();
const countBy = (val) => results.filter((r) => r.outcome === val).length;

const failedItems = results
  .filter((r) => r.outcome === 'validation_failed' || r.outcome === 'infrastructure_failed')
  .slice(0, 50)
  .map((r) => ({ company_name: r.company_name, outcome: r.outcome, reason: r.reason }));

return [{ json: {
  runId: cfg.discoveryRunId,
  mode: cfg.mode,
  environment: cfg.environment,
  inputCount: results.length,
  validCount: results.filter((r) => r.outcome !== 'validation_failed').length,
  createdNew: countBy('created_new'),
  resolvedExisting: countBy('resolved_existing'),
  staged: countBy('staged'),
  validationFailed: countBy('validation_failed'),
  infrastructureFailed: countBy('infrastructure_failed'),
  failedItems,
  totalDurationMs: Date.now() - startedAtMs,
  finishedAt: new Date().toISOString(),
} }];
